CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('BANK','BROKER')), name TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'TWD', broker TEXT, account_no TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_accounts_type ON accounts(type);
CREATE INDEX IF NOT EXISTS ix_accounts_status ON accounts(status);
CREATE TABLE IF NOT EXISTS securities (id TEXT PRIMARY KEY, symbol TEXT NOT NULL UNIQUE, exchange TEXT NOT NULL DEFAULT 'TW', currency TEXT NOT NULL DEFAULT 'TWD', name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('STOCK','ETF','FUND')), sector TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_securities_symbol ON securities(symbol);
CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT, security_id TEXT REFERENCES securities(id) ON DELETE SET NULL, txn_date TEXT NOT NULL, type TEXT NOT NULL, qty NUMERIC, price NUMERIC, fees NUMERIC NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'TWD', fx_rate NUMERIC NOT NULL DEFAULT 1, amount NUMERIC NOT NULL DEFAULT 0, note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_transactions_account_date ON transactions(account_id,txn_date);
CREATE INDEX IF NOT EXISTS ix_transactions_security_date ON transactions(security_id,txn_date);
CREATE TABLE IF NOT EXISTS positions (account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, security_id TEXT NOT NULL REFERENCES securities(id) ON DELETE CASCADE, qty NUMERIC NOT NULL DEFAULT 0, avg_cost NUMERIC NOT NULL DEFAULT 0, realized_pl NUMERIC NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY(account_id,security_id));
CREATE TABLE IF NOT EXISTS prices (id TEXT PRIMARY KEY, security_id TEXT NOT NULL REFERENCES securities(id) ON DELETE CASCADE, date TEXT NOT NULL, open NUMERIC NOT NULL, high NUMERIC NOT NULL, low NUMERIC NOT NULL, close NUMERIC NOT NULL, volume NUMERIC NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'TWD', created_at TEXT NOT NULL, UNIQUE(security_id,date));
CREATE TABLE IF NOT EXISTS dividends (id TEXT PRIMARY KEY, security_id TEXT NOT NULL REFERENCES securities(id) ON DELETE CASCADE, ex_date TEXT NOT NULL, pay_date TEXT NOT NULL, amount_per_share NUMERIC NOT NULL, currency TEXT NOT NULL DEFAULT 'TWD', note TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fx_rates (id TEXT PRIMARY KEY, base_ccy TEXT NOT NULL, quote_ccy TEXT NOT NULL, date TEXT NOT NULL, rate NUMERIC NOT NULL, created_at TEXT NOT NULL, UNIQUE(base_ccy,quote_ccy,date));
CREATE TABLE IF NOT EXISTS cash_balances (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, snapshot_date TEXT NOT NULL, balance NUMERIC NOT NULL, currency TEXT NOT NULL DEFAULT 'TWD', note TEXT, created_at TEXT NOT NULL, UNIQUE(account_id,snapshot_date));
CREATE TABLE IF NOT EXISTS idempotency_keys (key TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, request_hash TEXT NOT NULL, response_status INTEGER NOT NULL, response_body TEXT, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revoked_tokens (token TEXT PRIMARY KEY, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, reason TEXT);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
